calls.command:
qlang 'get [/dependencies /devDependencies] | map ~(entries) | flat | filter ~(get /1 | startsWith "^") | map ~(get /0 | toString) | distinct | sort' < manifest.json
cat orders.csv | tail -n +5 | head; 
qlang --raw 'lines | drop 1 | filter ~(trim | count | gt 0) | map ~(split ",") | filter ~(get /5 | lower | eq "paid") | map ~(mulOf /3 /4) | sum' < orders.csv
